          <tr>
            <td>Sheet</td>
            <td data-testid="classic-due-total">{formatCents(people.reduce((sum, p) => sum + (totalOf(p) ?? 0n), 0n))}</td>
          </tr>
        </tfoot>
      </table>
    </section>
  );
}
